<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRoute} from 'vue-router'
import {usePayrollPage} from '../payrollPage'
import {chooseCompany} from '../payrollUi'
import {hours} from '../time'
import {monthEnd} from '../timekeepingUi'
import type {PayrollHomeData,Payslip} from '../payrollTypes'
import CdacCalculationDetails from '../components/CdacCalculationDetails.vue'
import PayrollEvidence from '../components/PayrollEvidence.vue'
import PayBreakdownSummary from '../components/PayBreakdownSummary.vue'
import {wageBreakdown} from '../payBreakdown'
import PhaseStatus from '../components/PhaseStatus.vue'
const route=useRoute(),id=String(route.params.id),employeeId=typeof route.params.employeeId==='string'?route.params.employeeId:'',admin=!!employeeId,{api,r,t,base,loading,failure,load,english}=usePayrollPage(),data=ref<Payslip|null>(null)
onMounted(()=>void load(async()=>{if(admin){const h=await api().get<PayrollHomeData>('/payroll-home');chooseCompany(h,'');return api().get<Payslip>('/payroll-batches/'+id+'/payslips/'+employeeId)}return api().get<Payslip>('/my-payslips/'+id)},v=>data.value=v))
const fixed=computed(()=>data.value?.line.rule?.generation?.mode==='fixed')
function print(){window.print()}
function componentKind(kind:string){switch(kind){case 'basic':return r('basicPay');case 'overtime':return r('overtimePay');case 'ow_allowance':return r('ow_allowance');case 'reimbursement':return r('reimbursement');case 'deduction':return r('deduction');case 'employer_charge':return r('employerBorne');default:return '—'}}
function sdlText(value:string|undefined){if(!value)return '—';return value.includes('.')?value.replace(/0+$/,'').replace(/\.$/,''):value}
</script>
<template><section class="wf-panel wf-payslip"><header class="wf-toolbar wf-no-print"><h2>{{r('payslip')}}</h2><button v-if="data" @click="print">{{r('print')}}</button></header><PhaseStatus :failure="failure" :loading="loading"/><article v-if="data&&!loading" class="wf-pay-document"><header><h2>{{data.companyName}}</h2><p>{{r('payslip')}} · {{data.month}} · SGD</p></header><p><strong>{{english()?'Net payable this period':'本期应实发'}} SGD {{data.line.netPay??'—'}}</strong></p><p class="wf-hint">{{english()?'Published payslip: payment is recorded separately and is not proof of bank receipt.':'工资单已发布；付款另行登记，不代表银行已经到账。'}}</p><dl class="wf-details"><dt>{{r('employee')}}</dt><dd>{{data.line.employeeName}} · {{data.line.employeeNo}}</dd><dt>{{r('salaryPeriod')}}</dt><dd>{{data.month}}-01 – {{monthEnd(data.month+'-01')}}</dd><dt>{{t('status')}}</dt><dd>{{r(data.status)}}</dd><dt>{{r('basis')}}</dt><dd>{{data.line.rule?r(data.line.rule.basis):'—'}}</dd><dt>{{r('rate')}}</dt><dd>{{data.line.rule?.rate||'—'}}</dd><template v-if="!fixed&&data.line.rule?.basis==='monthly'"><dt>{{r('workingDays')}}</dt><dd>{{data.line.input?.workingDays||'—'}}</dd></template><template v-if="!fixed&&(data.line.rule?.basis==='monthly'||data.line.rule?.basis==='daily')"><dt>{{r('payableDays')}}</dt><dd>{{data.line.input?.payableDays||'—'}}</dd></template><template v-if="!fixed&&!data.line.hours"><dt>{{r('normal')}}</dt><dd>{{hours(data.line.normalSeconds)}}</dd><dt>{{r('overtime')}}</dt><dd>{{hours(data.line.overtimeSeconds)}}</dd><dt>{{r('paidLeave')}}</dt><dd>{{hours(data.line.paidLeaveSeconds)}}</dd><dt>{{r('unpaidLeave')}}</dt><dd>{{hours(data.line.unpaidLeaveSeconds)}}</dd></template></dl><p v-if="fixed" class="wf-hint">{{r('fixedSalaryHint')}}</p><details><summary>{{english()?'View hours and calculation evidence':'查看工时及计算依据'}}</summary><PayrollEvidence :line="data.line" :hide-governance="!admin"/></details><PayBreakdownSummary :value="data.breakdown||wageBreakdown(data.line)" details business-labels/><CdacCalculationDetails v-if="data.cdacCalculation" :value="data.cdacCalculation"/><p class="wf-hint">{{r('statutoryBase')}}: {{data.line.grossPay??(english()?'Unknown':'未知')}} · {{data.line.cpfRateCode}}</p><p class="wf-hint">{{r('sdlHint')}}</p><p>{{r('paymentPlan')}}: {{data.payment?r(data.payment.method):r('paymentUnknown')}} · {{r('bankName')}}: {{data.payment?.bank||'—'}}</p><p>{{r('paid')}} {{data.paidAmount}} · {{r('remaining')}} {{data.remainingAmount}}</p><h2 class="wf-section">{{r('paymentHistory')}}</h2><div class="wf-table-wrap"><table><thead><tr><th>{{r('paymentDate')}}</th><th>{{r('method')}}</th><th>{{r('bankName')}}</th><th>{{r('reference')}}</th><th>{{r('amount')}}</th></tr></thead><tbody><tr v-for="v in data.payments" :key="v.id"><td>{{v.paymentDate}}</td><td>{{r(v.method)}}</td><td>{{v.bank||'—'}}</td><td>{{v.reference}}</td><td>{{v.reversesId?'−':''}}{{v.amount}}</td></tr><tr v-if="!data.payments.length"><td colspan="5">{{r('unpaidStatus')}}</td></tr></tbody></table></div></article><footer v-if="data" class="wf-section wf-no-print"><RouterLink :to="admin?base+'/payroll-batches/'+id:base+'/payslips'">{{t('back')}}</RouterLink></footer></section></template>

